// src/utils.ts
var sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
var RATE_LIMIT_STATUS_CODE = 429;
var SERVICE_UNAVAILABLE_STATUS_CODE = 503;
var RETRYABLE_STATUS = [
  408,
  425,
  RATE_LIMIT_STATUS_CODE,
  500,
  502,
  SERVICE_UNAVAILABLE_STATUS_CODE,
  504
];
var BASE_DELAY_MS = 300;
var MAX_DELAY_MS = 1e4;
var backoff = (attempt) => {
  const exp = Math.min(MAX_DELAY_MS, BASE_DELAY_MS * 2 ** attempt);
  const jitter = Math.random() * exp * 0.3;
  return Math.floor(exp + jitter);
};
var isTimeoutError = (err) => err?.name === "TimeoutError";

// src/client.ts
var DEFAULT_TIMEOUT_IN_MS = 5000;
var NO_CONTENT_STATUS_CODE = 204;
var asFailure = (error) => ({ data: null, error, success: false });
var createREST = (options = {}) => {
  const makeURL = (route, query) => {
    const base = `${options.base ?? "https://api.abacatepay.com/v"}${options.version ?? 2}${route}`;
    return query ? `${base}?${new URLSearchParams(query)}` : base;
  };
  const makeHeaders = (custom) => {
    const {
      secret = process.env.ABACATEPAY_SECRET ?? process.env.ABACATEPAY_API_KEY
    } = options;
    if (!secret)
      return null;
    return {
      "Content-Type": "application/json",
      Authorization: `Bearer ${secret}`,
      ...options.headers,
      ...custom
    };
  };
  const parseResponse = async (response) => {
    if (response.status === NO_CONTENT_STATUS_CODE)
      return { data: null, error: null, success: true };
    return await response.json();
  };
  const handleTimeout = async ({
    retry,
    route,
    attempt,
    requestOptions
  }) => {
    if (attempt >= retry.max)
      return asFailure(`${retry.max} attempts were performed, all failed`);
    if (retry.onRetry)
      await retry.onRetry({ attempt, options: requestOptions });
    const delay = (retry.backoff ?? backoff)(attempt);
    await sleep(delay);
    return makeRequest(route, requestOptions, attempt + 1);
  };
  const handleError = async ({
    route,
    retry,
    requestOptions,
    attempt,
    response
  }) => {
    if (!RETRYABLE_STATUS.includes(response.status)) {
      const body = await response.json().catch(() => null);
      return asFailure(body?.error ?? `Request to ${route} failed with status ${response.status}`);
    }
    const { onRateLimit } = options;
    if (attempt >= retry.max)
      return asFailure(`${retry.max} attempts were performed, all failed`);
    if (retry.onRetry)
      await retry.onRetry({ attempt, options: requestOptions, response });
    if (response.status === RATE_LIMIT_STATUS_CODE && onRateLimit)
      await onRateLimit(response);
    const delay = (retry.backoff ?? backoff)(attempt);
    await sleep(delay);
    return makeRequest(route, requestOptions, attempt + 1);
  };
  const makeRequest = async (route, requestOptions, attempt = 0) => {
    const headers = makeHeaders(requestOptions.headers);
    if (!headers)
      return asFailure("We could not find any AbacatePay secret, use REST({ secret })");
    const url = makeURL(route, requestOptions.query);
    const { timeout = DEFAULT_TIMEOUT_IN_MS } = options;
    const retry = requestOptions.retry ?? options.retry ?? { max: 3 };
    try {
      const response = await fetch(url, {
        method: requestOptions.method,
        signal: AbortSignal.timeout(timeout),
        headers,
        body: "body" in requestOptions ? JSON.stringify(requestOptions.body) : null
      });
      if (!response.ok)
        return handleError({
          route,
          retry,
          attempt,
          requestOptions,
          response
        });
      return parseResponse(response);
    } catch (err) {
      if (isTimeoutError(err))
        return handleTimeout({ retry, route, attempt, requestOptions });
      return asFailure(`${err}`);
    }
  };
  const client = {
    options,
    setSecret(secret) {
      options.secret = secret;
      return client;
    },
    get(route, requestOptions) {
      return makeRequest(route, { ...requestOptions, method: "GET" });
    },
    post(route, requestOptions) {
      return makeRequest(route, { ...requestOptions, method: "POST" });
    },
    delete(route, requestOptions) {
      return makeRequest(route, { ...requestOptions, method: "DELETE" });
    },
    put(route, requestOptions) {
      return makeRequest(route, { ...requestOptions, method: "PUT" });
    },
    patch(route, requestOptions) {
      return makeRequest(route, { ...requestOptions, method: "PATCH" });
    }
  };
  return client;
};
// src/version.ts
var version = "1.0.2";
var API_VERSION = "2";
export {
  version,
  createREST,
  RETRYABLE_STATUS,
  API_VERSION
};
